import { useId } from 'react';
import styled from 'styled-components';

import { DemoHint, DemoPanel } from './LandingDemoStyles';
import { Fretboard } from './VirtualGuitar/Fretboard';
import {
  Board,
  BoardPanel,
  Cell,
  Feedback,
  Neck,
  NeckScroll,
} from './VirtualGuitar/styles';

export const LandingGuitar = ({ visible }: { visible: boolean }) => {
  const hint = useId();
  return (
    <DemoPanel role="group" aria-label="Guitar" aria-describedby={hint}>
      <EmbeddedFretboard enabled={visible} />
      <DemoHint id={hint}>
        Press a fret. Drag sideways to slide or vertically to bend.
      </DemoHint>
    </DemoPanel>
  );
};

const EmbeddedFretboard = styled(Fretboard)`
  flex: 1;
  grid-template-rows: auto 1fr;

  & ${BoardPanel}, & ${Neck} {
    display: flex;
    flex-direction: column;
  }

  & ${BoardPanel} {
    padding: 8px 10px 10px;
  }

  & ${NeckScroll} {
    display: flex;
    flex: 1;
  }

  & ${Neck}, & ${Board} {
    flex: 1;
  }

  & ${Board} {
    grid-auto-rows: minmax(32px, 1fr);
  }

  & ${Cell} {
    min-height: 32px;
  }

  & ${Feedback}, & ${Feedback}:empty {
    display: flex;
    min-height: 32px;
    margin-top: 6px;
  }
`;
