import { useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { batch, useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import styled from 'styled-components';

import { formatPitch, pitchClass } from 'app/services/ChordsService';
import { selectEffects } from 'app/services/EffectsService/selectors';
import { scaleLabels } from 'app/services/MelodiesService/scaleOptimization';
import { MAX_TEMPO, MIN_TEMPO } from 'app/services/MelodiesService/tempo';
import { useLibraryPlayback } from 'app/services/MelodiesService/useLibraryPlayback';
import { downloadBlob, downloadMelody } from 'app/services/MelodyExportService';
import { MelodyExportError } from 'app/services/MelodyExportService/errors';
import {
  Phrase,
  composePhrase,
} from 'app/services/MelodyGenerationService/compose';
import {
  GenerationSettings,
  MAX_BARS,
  MIN_BARS,
  defaultSettings,
  moods,
  rhythms,
  timbrePrograms,
  tonics,
} from 'app/services/MelodyGenerationService/options';
import {
  encodePhraseMidi,
  phrasePlayback,
  phraseRecordingProject,
} from 'app/services/MelodyGenerationService/output';
import { notesActions, selectNotes } from 'app/services/NotesService';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import {
  Mode,
  Scale,
  getScale,
  scales,
  selectSettings,
  settingsActions,
} from 'app/services/SettingsService';
import { microtonalPreset } from 'app/services/SettingsService/microtonal';

import { getTimbrePresentation } from 'app/components/TimbrePicker/catalog';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

import { capitalize } from 'utils';

const modeLabels: Partial<Record<Mode, string>> = {
  ionian: 'Major (Ionian)',
  aeolian: 'Minor (Aeolian)',
  h1: 'Harmonic minor',
  j1: 'Melodic minor',
  p1: 'Major pentatonic',
  p5: 'Minor pentatonic',
  solo: '11 degrees',
  custom: 'Custom',
};
const modeLabel = (scale: Scale, mode: Mode) =>
  microtonalPreset(scale, mode)?.label ?? modeLabels[mode] ?? capitalize(mode);
const keyLabel = ({ tonic, scale, mode }: Phrase) => {
  const label =
    mode === 'ionian'
      ? 'major'
      : mode === 'aeolian'
      ? 'minor'
      : modeLabel(scale, mode);
  return `${formatPitch(tonic)} ${label}`;
};
const timbres = Object.keys(timbrePrograms) as GenerationSettings['timbre'][];
const moodChoices = Object.keys(moods).sort();
const formats = ['midi', 'wav', 'mp3'] as const;
type Format = typeof formats[number];

export const MelodyGeneratorPage = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { isRecording, customScale: studioNotes } = useSelector(selectSettings);
  const { instruments } = useSelector(selectEffects);
  const hasComposition = useSelector(state => {
    const { melody, project } = selectNotes(state);
    return !!(melody.notes.length || project);
  });
  const [settings, setSettings] = useState(() => ({
    ...defaultSettings,
    bpm: String(defaultSettings.bpm),
    bars: String(defaultSettings.bars),
    customScale: chromaticNotes.filter(
      note =>
        note === 'C' ||
        (studioNotes ?? getScale('diatonic', 'ionian')).includes(note),
    ),
  }));
  const [phrase, setPhrase] = useState<Phrase>();
  const [previewAttempted, setPreviewAttempted] = useState(false);
  const [format, setFormat] = useState<Format>('midi');
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState<{
    phrase: Phrase;
    message: string;
  }>();
  const playback = useLibraryPlayback({ loop: true });

  const download = async (piece: Phrase) => {
    setExportError(undefined);
    setExporting(true);
    try {
      if (format === 'midi') {
        downloadBlob(
          new Blob([encodePhraseMidi(piece)], { type: 'audio/midi' }),
          'generated-melody.mid',
        );
      } else {
        await downloadMelody(
          { ...phrasePlayback(piece), title: 'generated-melody' },
          format,
          instruments[piece.timbre],
        );
      }
    } catch (cause) {
      setExportError({
        phrase: piece,
        message:
          cause instanceof MelodyExportError
            ? cause.message
            : 'Could not prepare the file. Try again.',
      });
    } finally {
      setExporting(false);
    }
  };

  const openPhrase = (target: 'studio' | 'play-along') => {
    if (!phrase || isRecording) return;
    if (
      hasComposition &&
      !window.confirm('Replace the current composition with this melody?')
    )
      return;
    const project = phraseRecordingProject(phrase);
    playback.stop();
    batch(() => {
      dispatch(notesActions.loadRecordingProject(project));
      dispatch(settingsActions.loadMelodySettings(project.tracks[0].melody));
    });
    if (target === 'studio')
      navigate('/sandbox/staff', { state: { editRecording: true } });
    else navigate('/play-along/recording');
  };

  return (
    <Page>
      <Helmet>
        <title>Generate a melody</title>
        <meta
          name="description"
          content="Generate a melody with chords in any scale. Hear it on repeat, open it in Melody Studio or Play Along, or download MIDI, WAV or MP3."
        />
      </Helmet>
      <header>
        <h1>Generate a melody</h1>
        <p>
          Choose your settings to create a melody and accompaniment in your
          browser.
        </p>
      </header>
      <Panel
        as="form"
        onSubmit={event => {
          event.preventDefault();
          playback.stop();
          setPreviewAttempted(false);
          setPhrase(
            composePhrase({
              ...settings,
              bpm: Number(settings.bpm),
              bars: Number(settings.bars),
              customScale:
                settings.scale === 'custom' ? settings.customScale : undefined,
            }),
          );
        }}
      >
        <Settings>
          <Field>
            <label htmlFor="generator-tempo">Tempo (BPM)</label>
            <input
              id="generator-tempo"
              type="number"
              min={MIN_TEMPO}
              max={MAX_TEMPO}
              required
              value={settings.bpm}
              onChange={event =>
                setSettings({ ...settings, bpm: event.target.value })
              }
            />
          </Field>
          <Field>
            <label htmlFor="generator-tonic">Tonic</label>
            <select
              id="generator-tonic"
              value={settings.tonic}
              onChange={event =>
                setSettings({
                  ...settings,
                  tonic: event.target.value as GenerationSettings['tonic'],
                })
              }
            >
              {tonics.map(tonic => (
                <option key={tonic} value={tonic}>
                  {formatPitch(tonic)}
                </option>
              ))}
            </select>
          </Field>
          <Field>
            <label htmlFor="generator-scale">Scale</label>
            <select
              id="generator-scale"
              value={settings.scale}
              onChange={event => {
                const scale = event.target.value as Scale;
                setSettings({
                  ...settings,
                  scale,
                  mode: scales[scale].modes[0],
                });
              }}
            >
              {(Object.keys(scales) as Scale[]).map(scale => (
                <option key={scale} value={scale}>
                  {scale === 'custom' ? 'Custom' : scaleLabels[scale]}
                </option>
              ))}
            </select>
          </Field>
          <Field>
            <label htmlFor="generator-mode">Mode</label>
            <select
              id="generator-mode"
              value={settings.mode}
              onChange={event =>
                setSettings({ ...settings, mode: event.target.value as Mode })
              }
            >
              {scales[settings.scale].modes.map(mode => (
                <option key={mode} value={mode}>
                  {modeLabel(settings.scale, mode)}
                </option>
              ))}
            </select>
          </Field>
          <Field>
            <label htmlFor="generator-length">Length (bars)</label>
            <input
              id="generator-length"
              type="number"
              min={MIN_BARS}
              max={MAX_BARS}
              required
              value={settings.bars}
              onChange={event =>
                setSettings({ ...settings, bars: event.target.value })
              }
            />
          </Field>
          <Field>
            <label htmlFor="generator-timbre">Timbre</label>
            <select
              id="generator-timbre"
              value={settings.timbre}
              onChange={event =>
                setSettings({
                  ...settings,
                  timbre: event.target.value as GenerationSettings['timbre'],
                })
              }
            >
              {timbres.map(timbre => (
                <option key={timbre} value={timbre}>
                  {getTimbrePresentation(timbre).label}
                </option>
              ))}
            </select>
          </Field>
          <Field>
            <label htmlFor="generator-rhythm">Rhythm</label>
            <select
              id="generator-rhythm"
              value={settings.rhythm}
              onChange={event =>
                setSettings({
                  ...settings,
                  rhythm: event.target.value as GenerationSettings['rhythm'],
                })
              }
            >
              {Object.keys(rhythms).map(rhythm => (
                <option key={rhythm}>{rhythm}</option>
              ))}
            </select>
          </Field>
          <Field>
            <label htmlFor="generator-mood">Melody mood</label>
            <select
              id="generator-mood"
              value={settings.mood}
              onChange={event =>
                setSettings({
                  ...settings,
                  mood: event.target.value as GenerationSettings['mood'],
                })
              }
            >
              {moodChoices.map(mood => (
                <option key={mood}>{mood}</option>
              ))}
            </select>
          </Field>
        </Settings>
        {settings.scale === 'custom' && (
          <CustomNotes>
            <legend>Scale notes</legend>
            {chromaticNotes.map((note, index) => (
              <label key={note}>
                <input
                  type="checkbox"
                  checked={settings.customScale.includes(note)}
                  disabled={index === 0}
                  onChange={({ target }) =>
                    setSettings({
                      ...settings,
                      customScale: chromaticNotes.filter(candidate =>
                        candidate === note
                          ? target.checked
                          : settings.customScale.includes(candidate),
                      ),
                    })
                  }
                />
                {formatPitch(
                  chromaticNotes[(pitchClass(settings.tonic) + index) % 12],
                )}
              </label>
            ))}
          </CustomNotes>
        )}
        <Actions>
          <button type="submit" className="selected">
            Generate melody
          </button>
        </Actions>
      </Panel>
      {phrase && (
        <Panel aria-labelledby="generated-melody">
          <h2 id="generated-melody">Your melody</h2>
          <p role="status">
            {keyLabel(phrase)} · {phrase.bpm} BPM · {phrase.bars} bars in 4/4
          </p>
          <p>
            {getTimbrePresentation(phrase.timbre).label} · {phrase.rhythm} ·{' '}
            {phrase.mood}
          </p>
          <h3>Chord progression</h3>
          <Progression>
            {phrase.chords.map((chord, bar) => (
              <li key={bar}>
                <span>Bar {bar + 1}</span> <strong>{chord}</strong>
              </li>
            ))}
          </Progression>
          <Actions>
            <button
              type="button"
              onClick={() => {
                if (playback.activeTitle) playback.stop();
                else {
                  setPreviewAttempted(true);
                  void playback.toggle(phrasePlayback(phrase));
                }
              }}
            >
              {playback.activeTitle ? 'Stop preview' : 'Play preview'}
            </button>
            <button
              type="button"
              disabled={isRecording}
              onClick={() => openPhrase('studio')}
            >
              Open in Melody Studio
            </button>
            <button
              type="button"
              disabled={isRecording}
              onClick={() => openPhrase('play-along')}
            >
              Open in Play Along
            </button>
          </Actions>
          <Actions
            role="group"
            aria-label="Download melody"
            aria-busy={exporting}
          >
            <select
              aria-label="Download format"
              value={format}
              disabled={exporting}
              onChange={event => {
                setFormat(event.target.value as Format);
                setExportError(undefined);
              }}
            >
              {formats.map(format => (
                <option key={format} value={format}>
                  {format.toUpperCase()}
                </option>
              ))}
            </select>
            <button
              type="button"
              disabled={exporting}
              onClick={() => void download(phrase)}
            >
              {exporting
                ? 'Preparing file…'
                : `Download ${format.toUpperCase()}`}
            </button>
          </Actions>
          {exportError?.phrase === phrase && (
            <ErrorText role="alert">{exportError.message}</ErrorText>
          )}
          {isRecording && <p>Stop recording before opening this melody.</p>}
          {playback.loading && <p role="status">Loading sound…</p>}
          {previewAttempted && playback.error && (
            <ErrorText role="alert">{playback.error}</ErrorText>
          )}
        </Panel>
      )}
    </Page>
  );
};

const Page = styled(PageWrapper)`
  max-width: 880px;
  display: grid;
  gap: 20px;

  h1 {
    margin: 0 0 6px;
    text-align: left;
    font-family: inherit;
    font-size: clamp(28px, 4vw, 44px);
    font-weight: 680;
  }

  p {
    margin: 0;
    color: ${p => p.theme.textSecondary};
  }
`;

const Panel = styled.section`
  display: grid;
  gap: 16px;
  padding: clamp(12px, 3vw, 20px);
  border: 1px solid ${p => p.theme.border};
  border-radius: 14px;
  background: ${p => p.theme.surface};

  h2 {
    font-size: 20px;
  }

  h3 {
    font-size: 16px;
    font-weight: 650;
  }
`;

const Settings = styled.div`
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;

  @media (max-width: 650px) {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  @media (max-width: 420px) {
    grid-template-columns: minmax(0, 1fr);
  }
`;

const Field = styled.div`
  display: grid;
  gap: 6px;
  min-width: 0;

  label {
    font-weight: 650;
  }

  input[type='number'],
  select {
    width: 100%;
    background: ${p => p.theme.backgroundVariant};
    font-size: 16px;
    font-weight: 400;
  }
`;

const Actions = styled.div`
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
`;

const CustomNotes = styled.fieldset`
  display: flex;
  flex-wrap: wrap;
  gap: 10px 16px;
  min-width: 0;
  margin: 0;
  padding: 8px 0 0;
  border: 0;

  label {
    display: flex;
    align-items: center;
    gap: 5px;
  }
`;

const Progression = styled.ol`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(64px, 1fr));
  gap: 6px;
  margin: 0;
  padding: 0;
  list-style: none;

  li {
    display: grid;
    gap: 4px;
    padding: 8px;
    border-radius: 8px;
    background: ${p => p.theme.backgroundVariant};
    overflow-wrap: anywhere;
  }

  span {
    color: ${p => p.theme.textSecondary};
    font-size: 12px;
  }
`;

const ErrorText = styled.p`
  && {
    color: ${p => p.theme.danger};
  }
`;
