const Arrow = () => <span aria-hidden="true">→</span>;

export const LandingPage = () => {
  const { hash } = useLocation();
  const navigationType = useNavigationType();
  useEffect(() => {
    if (hash === '#features') {
      document.getElementById('features')?.scrollIntoView();
    } else if (navigationType === 'PUSH') {
      window.scrollTo(0, 0);
    }
  }, [hash, navigationType]);

  return (
    <>
      <SiteHeader
        navigation={
          <HeaderNav aria-label="Tools">
            <HeaderLink to="/generate-melody">Generate a melody</HeaderLink>
            <HeaderLink to={sandbox}>Melody Studio</HeaderLink>
            <HeaderLink to="/play-along">Play Along</HeaderLink>
            <HeaderLink to="/guitar-amp">Guitar amp</HeaderLink>
            <HeaderLink to="/drum-machine">Drum Machine</HeaderLink>
          </HeaderNav>
        }
        controls={<ThemeSwitch />}
      />
      <Content>
        <Hero>
          <div>
            <h1>
              Play music <em>in your browser</em>
            </h1>
            <HeroCopy>
              Try the piano, guitar, or drum machine here. In Melody Studio, you
              can record a melody and see it as sheet music or tabs.
            </HeroCopy>
            <HeroActions>
              <PrimaryLink to={sandbox}>
                Open Melody Studio <Arrow />
              </PrimaryLink>
              <SecondaryLink href="#features">Explore features</SecondaryLink>
            </HeroActions>
            <Inputs>
              You can also connect a MIDI keyboard, guitar, or mic in Melody
              Studio.
            </Inputs>
          </div>
          <LandingInstruments />
        </Hero>

        <Features id="features" aria-labelledby="features-heading">
          <h2 id="features-heading">What you can do</h2>
          {groups.map(({ title, artwork, mirrorArtwork, tools }) => (
            <FeatureGroup key={artwork} aria-labelledby={`feature-${artwork}`}>
              <FeatureCover $mirrored={mirrorArtwork}>
                <img
                  src={`${featureArtworkPath}/${artwork}.webp`}
                  alt=""
                  width={1920}
                  height={640}
                  loading="lazy"
                  decoding="async"
                />
                <FeatureHeading>
                  <h3 id={`feature-${artwork}`}>{title}</h3>
                </FeatureHeading>
              </FeatureCover>
              <ToolList $columns={tools.length}>
                {tools.map(({ title, path, icon, description }) => {
                  const content = (
                    <>
                      <ToolIcon>
                        <HeaderIcon name={icon} />
                      </ToolIcon>
                      {path && <Arrow />}
                      <ToolCopy>
                        <strong>{title}</strong>
                        <span>{description}</span>
                      </ToolCopy>
                    </>
                  );

                  return (
                    <li key={title}>
                      {path ? (
                        <ToolCard as={Link} to={path}>
                          {content}
                        </ToolCard>
                      ) : (
                        <ToolCard>{content}</ToolCard>
                      )}
                    </li>
                  );
                })}
              </ToolList>
            </FeatureGroup>
          ))}
        </Features>
        <PlayCallout aria-labelledby="play-heading">
          <div>
            <h2 id="play-heading">Play your first melody</h2>
            <p>
              Use your computer keyboard or the onscreen piano. Press Record to
              capture your notes as sheet music or tabs.
            </p>
          </div>
          <PrimaryLink to={sandbox}>
            Start playing <Arrow />
          </PrimaryLink>
        </PlayCallout>
      </Content>
      <Footer>
        Author:{' '}
        <a
          href="https://polyakovin.ru/"
          target="_blank"
          rel="author noopener noreferrer"
          title="Melody Generator author's website (opens in a new tab)"
        >
          Igor Polyakov
        </a>
      </Footer>
    </>
  );
};

