import { useEffect } from 'react';
import { useSelector } from 'react-redux';
import { Link } from 'react-router-dom';
import styled from 'styled-components';

import {
  chordSymbol,
  detectChords,
  formatPitch,
} from 'app/services/ChordsService';
import { useConnectedGuitarInput } from 'app/services/GuitarInputService/context';
import { selectSoundingNotes } from 'app/services/NotesService';

import { FeatureHeading } from 'app/components/FeatureHeading';
import { InputDevicesSlot } from 'app/components/InputDevices';
import { MetronomeSlot } from 'app/components/Metronome';
import { SandboxInstrument } from 'app/components/SandboxInstrument';
import { PageWrapper } from 'app/components/_styled/PageWrapper';

export const MetronomePage = () => (
  <NarrowPage>
    <FeatureHeading
      title="Metronome"
      description="Set the tempo, time signature, and rhythm. Start the click to hear the accents."
    />
    <MetronomeSlot />
  </NarrowPage>
);

export const ChordRecognitionPage = () => {
  const sounding = useSelector(selectSoundingNotes);
  const matches = detectChords(sounding).map(chordSymbol);

  return (
    <PageWrapper>
      <FeatureHeading
        title="Chord recognition"
        description="Hold three or four different notes on your computer keyboard, onscreen piano, or MIDI controller."
      />
      <ChordResult aria-live="polite" role="status">
        <strong>
          {matches.length
            ? matches.join(' / ')
            : sounding.length >= 3
            ? 'No exact match'
            : 'Play a chord'}
        </strong>
        {sounding.length > 0 && (
          <span>{sounding.map(formatPitch).join(' · ')}</span>
        )}
      </ChordResult>
      <SandboxInstrument inline />
      <Link to="/sandbox/staff">
        Open Melody Studio to connect a MIDI controller
      </Link>
    </PageWrapper>
  );
};

export const GuitarAmpPage = () => {
  const { stopAmpRecording } = useConnectedGuitarInput();
  useEffect(() => stopAmpRecording, [stopAmpRecording]);

  return (
    <PageWrapper>
      <FeatureHeading
        title="Use your computer as a guitar amp"
        description="Connect your guitar through an audio interface to hear it with effects. Record a take to download a clean or processed WAV."
      />
      <InputDevicesSlot placement="amp" />
    </PageWrapper>
  );
};

const NarrowPage = styled(PageWrapper)`
  max-width: 600px;
`;

const ChordResult = styled.div`
  display: grid;
  gap: 8px;
  margin-bottom: 20px;
  padding: 16px;
  border: 1px solid ${p => p.theme.border};
  border-radius: 8px;
  background: ${p => p.theme.surface};

  strong {
    font-size: 1.375rem;
  }
`;
