import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import { useSelector, useStore } from 'react-redux';

import type { RealtimeFrame } from 'app/services/GuitarInputService/polyphonicStream';
import {
  getMelodyDuration,
  getNoteDuration,
  playMelody,
  stopMelody,
} from 'app/services/MelodiesService';
import { cropExpression } from 'app/services/MelodiesService/expression';
import { Melody } from 'app/services/MelodiesService/types';
import {
  Note,
  notesActions,
  selectSoundingNotes,
} from 'app/services/NotesService';
import { setLiveNotePlaybackFilter } from 'app/services/NotesService/livePlayback';
import { selectSettings } from 'app/services/SettingsService';
import {
  Timbre,
  loadSound,
  resumeAudio,
} from 'app/services/SynthesizerService';
import { RootState } from 'app/services/types';

import {
  HIT_WINDOW,
  LEAD_IN,
  PracticeMode,
  Session,
  advanceSession,
  createSession,
  getNextTargets,
  judgeNote,
  judgeWaitingNote,
  releaseWaitingNotes,
} from './game';
import { createPlaybackTimeline } from './timeline';

type Mode = 'practice' | 'listen';
type Status = 'ready' | 'playing' | 'paused' | 'finished';
type View = {
  status: Status;
  mode: Mode;
  practiceMode: PracticeMode;
  elapsed: number;
  session: Session;
};

export const usePlayAlong = (
  melody: Melody,
  speed: number,
  practiceMode: PracticeMode = 'rhythm',
  hitWindow = HIT_WINDOW,
  muteWrongNotes = true,
  inputSource: 'keys' | 'guitar' | 'none' = 'keys',
  guide?: { sound: boolean; timbre: Timbre },
) => {
  const store = useStore<RootState>();
  const settings = useSelector(selectSettings);
  const timbre = guide?.timbre ?? settings.timbre;
  const guideSound = guide?.sound ?? true;
  const timeline = useMemo(
    () => createPlaybackTimeline(melody.notes, hitWindow),
    [melody.notes, hitWindow],
  );
  const currentSpeed = useRef(speed);
  currentSpeed.current = speed;
  const initialView = useCallback(
    (): View => ({
      status: 'ready',
      mode: 'practice',
      practiceMode,
      elapsed: -LEAD_IN * currentSpeed.current,
      session: createSession(melody.notes.length),
    }),
    [melody, practiceMode],
  );
  const [view, setView] = useState(initialView);
  const current = useRef(view);
  const clock = useRef({ song: view.elapsed, wall: 0, speed });
  const request = useRef({ id: 0 });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const duration = getMelodyDuration(melody);
  const finishAt = Math.max(
    duration,
    ...melody.notes.map(note => note.start + hitWindow * speed),
  );

  const update = useCallback((next: View) => {
    current.current = next;
    setView(next);
  }, []);

  const now = useCallback(() => {
    const state = current.current;
    if (state.status !== 'playing') return state.elapsed;
    const { song, wall, speed } = clock.current;
    const elapsed = performance.now() - wall;
    if (elapsed === 0) return song;
    const time = timeline.toSongTime(
      timeline.toPlaybackTime(song, speed) + elapsed * speed,
      speed,
    );
    if (practiceMode !== 'wait' || state.mode !== 'practice') return time;
    const [next] = getNextTargets(state.session, melody.notes);
    return next === undefined ? time : Math.min(time, melody.notes[next].start);
  }, [melody.notes, practiceMode, timeline]);

  useLayoutEffect(
    () =>
      setLiveNotePlaybackFilter(note => {
        const state = current.current;
        if (
          inputSource !== 'keys' ||
          !muteWrongNotes ||
          state.status !== 'playing' ||
          state.mode !== 'practice'
        )
          return true;
        const time = now();
        if (time < -hitWindow * speed) return false;
        const judge = practiceMode === 'wait' ? judgeWaitingNote : judgeNote;
        return (
          judge(state.session, melody.notes, note, time, speed, hitWindow)
            .wrongNotes === state.session.wrongNotes
        );
      }),
    [
      hitWindow,
      inputSource,
      melody.notes,
      muteWrongNotes,
      now,
      practiceMode,
      speed,
    ],
  );

  useLayoutEffect(() => {
    const previousSpeed = clock.current.speed;
    if (previousSpeed === speed) return;
    const state = current.current;
    const position = now();
    const elapsed =
      position < 0 ? (position / previousSpeed) * speed : position;
    clock.current = { song: elapsed, wall: performance.now(), speed };
    update({ ...state, elapsed });
  }, [now, speed, update]);

  const releaseNotes = useCallback(() => {
    const state = store.getState();
    const { timbre } = selectSettings(state);
    selectSoundingNotes(state).forEach(note =>
      store.dispatch(notesActions.muteNote({ note, timbre, allSources: true })),
    );
  }, [store]);

  const reset = useCallback(() => {
    request.current.id++;
    update(initialView());
    stopMelody();
    releaseNotes();
    setLoading(false);
    setError('');
  }, [initialView, releaseNotes, update]);

  useLayoutEffect(() => {
    reset();
    const pending = request.current;
    return () => {
      pending.id++;
      current.current.status = 'ready';
      stopMelody();
      releaseNotes();
    };
  }, [reset, releaseNotes, inputSource]);

  const start = useCallback(
    async (mode: Mode = 'practice') => {
      const id = ++request.current.id;
      setError('');
      setLoading(true);
      try {
        if (mode === 'listen' ? guideSound : inputSource === 'keys') {
          await Promise.all([resumeAudio(), loadSound(timbre)]);
        }
        if (id !== request.current.id) return;
        const previous = current.current;
        const resume = previous.status === 'paused' && previous.mode === mode;
        const next = resume ? previous : { ...initialView(), mode };
        clock.current = {
          song: next.elapsed,
          wall: performance.now(),
          speed: currentSpeed.current,
        };
        update({ ...next, status: 'playing' });
        setLoading(false);
      } catch {
        if (id !== request.current.id) return;
        setLoading(false);
        setError('Could not load sound. Try again.');
      }
    },
    [guideSound, initialView, inputSource, timbre, update],
  );

  const pause = useCallback(() => {
    if (current.current.status !== 'playing') {
      request.current.id++;
      setLoading(false);
      return;
    }
    update({
      ...current.current,
      elapsed: now(),
      status: 'paused',
      session: releaseWaitingNotes(current.current.session, melody.notes, []),
    });
    stopMelody();
    releaseNotes();
  }, [melody.notes, now, releaseNotes, update]);

  useEffect(() => {
    const onVisibility = () => {
      if (document.hidden) pause();
    };
    window.addEventListener('blur', pause);
    document.addEventListener('visibilitychange', onVisibility);
    return () => {
      window.removeEventListener('blur', pause);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, [pause]);

  const handleNotes = useCallback(
    (attacks: Note[], notes: Note[]) => {
      const state = current.current;
      const time = now();
      let session =
        practiceMode === 'wait'
          ? releaseWaitingNotes(state.session, melody.notes, notes)
          : state.session;
      if (
        state.status !== 'playing' ||
        state.mode !== 'practice' ||
        time < -hitWindow * speed
      ) {
        if (session !== state.session) update({ ...state, session });
        return;
      }
      if (attacks.length) {
        const judge = practiceMode === 'wait' ? judgeWaitingNote : judgeNote;
        session = attacks.reduce(
          (session, note) =>
            judge(session, melody.notes, note, time, speed, hitWindow),
          session,
        );
        const [next] = getNextTargets(state.session, melody.notes);
        if (
          practiceMode === 'wait' &&
          next !== undefined &&
          time >= melody.notes[next].start
        ) {
          // Discard time spent at the gate, including partial chord input.
          // The next interval starts from the last required attack, never from
          // a wall clock that has kept running during the wait.
          clock.current = { song: time, wall: performance.now(), speed };
        }
      }
      if (session !== state.session) {
        update({
          ...state,
          elapsed: time,
          session,
        });
      }
    },
    [hitWindow, melody, now, practiceMode, speed, update],
  );

  // Score each attack before React batches a chord or a quick release.
  useEffect(() => {
    if (inputSource !== 'keys') return;
    let previous = selectSoundingNotes(store.getState());
    return store.subscribe(() => {
      const notes = selectSoundingNotes(store.getState());
      const attacks = notes.filter(note => !previous.includes(note));
      previous = notes;
      handleNotes(attacks, notes);
    });
  }, [handleNotes, inputSource, store]);

  const guitarVoices = useRef(new Map<Note, number>());
  const onGuitarFrame = useCallback(
    (frame: RealtimeFrame) => {
      if (inputSource !== 'guitar') return;
      const attacks: Note[] = [];
      frame.events.forEach(event => {
        const note = event.note.note;
        if (
          frame.soundingNotes.includes(note) &&
          guitarVoices.current.get(note) !== event.id
        ) {
          guitarVoices.current.set(note, event.id);
          attacks.push(note);
        }
      });
      guitarVoices.current.forEach((id, note) => {
        if (!frame.soundingNotes.includes(note))
          guitarVoices.current.delete(note);
      });
      handleNotes(attacks, frame.soundingNotes);
    },
    [handleNotes, inputSource],
  );

  useEffect(() => {
    if (view.status !== 'playing') return;
    let frame: number;
    let guideTimer: ReturnType<typeof setTimeout> | undefined;
    if (view.mode === 'listen' && guideSound) {
      const elapsed = now();
      guideTimer = setTimeout(() => {
        const offset = Math.max(0, elapsed);
        playMelody({
          ...melody,
          timbre,
          notes: melody.notes
            .filter(note => note.start + getNoteDuration(note) > offset)
            .map(note => ({
              ...note,
              ...(note.expression
                ? {
                    expression: cropExpression(
                      note.expression,
                      Math.max(0, offset - note.start) / getNoteDuration(note),
                    ),
                  }
                : {}),
              start:
                Math.max(
                  0,
                  timeline.toPlaybackTime(note.start, speed) -
                    timeline.toPlaybackTime(offset, speed),
                ) / speed,
              duration:
                (note.start +
                  getNoteDuration(note) -
                  Math.max(offset, note.start)) /
                speed,
            })),
        });
      }, Math.max(0, -elapsed / speed));
    }
    const tick = () => {
      if (current.current.status !== 'playing') return;
      const elapsed = now();
      const state = current.current;
      const finished = elapsed >= finishAt + 400 * speed;
      const session =
        state.mode === 'practice' && practiceMode === 'rhythm'
          ? advanceSession(
              state.session,
              melody.notes,
              elapsed,
              speed,
              hitWindow,
            )
          : state.session;
      // A held gate can last minutes. Keep checking input without redrawing an
      // unchanged instrument on every frame.
      if (finished || elapsed !== state.elapsed || session !== state.session) {
        update({
          ...state,
          elapsed: finished ? finishAt : elapsed,
          status: finished ? 'finished' : 'playing',
          session,
        });
      }
      if (finished) {
        stopMelody();
        releaseNotes();
      } else frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => {
      cancelAnimationFrame(frame);
      clearTimeout(guideTimer);
      stopMelody();
    };
  }, [
    finishAt,
    guideSound,
    hitWindow,
    melody,
    now,
    practiceMode,
    releaseNotes,
    speed,
    timbre,
    timeline,
    update,
    view.mode,
    view.status,
  ]);

  const next = getNextTargets(view.session, melody.notes);
  const waiting =
    practiceMode === 'wait' &&
    view.mode === 'practice' &&
    view.status === 'playing' &&
    next.length > 0 &&
    view.elapsed >= melody.notes[next[0]].start;
  const waitingNotes = waiting ? next.map(i => melody.notes[i].note) : [];
  return {
    ...view,
    onGuitarFrame,
    duration,
    waiting,
    waitingNotes,
    loading,
    error,
    start,
    pause,
    reset,
  };
};
