export type BuiltInEffectPreset = EffectPreset & {
  category: string;
  description: string;
  design: PedalDesign;
};
const eq = (low: number, mid: number, high: number) => ({
  equalizer: { enabled: true, low, mid, high },
});
const drive = (amount: number, tone: number) => ({
  distortion: { enabled: true, drive: amount, tone },
});
const comp = (threshold: number, ratio: number) => ({
  compressor: { enabled: true, threshold, ratio },
});
const chorus = (rate: number, depth: number, mix: number) => ({
  chorus: { enabled: true, rate, depth, mix },
});
const echo = (time: number, feedback: number, mix: number) => ({
  delay: { enabled: true, time, feedback, mix },
});
const room = (mix: number, tone: number) => ({
  reverb: { enabled: true, mix, tone },
});

const p = (
  id: string,
  name: string,
  description: string,
  look: PedalLook,
  effects: Partial<EffectStage>,
  tags = '',
): BuiltInEffectPreset => {
  const [finish, graphic] = look.split(':') as [
    PedalDesign['finish'],
    PedalDesign['graphic'],
  ];
  return {
    id,
    name,
    description,
    category: '',
    tags: tags.split(' '),
    design: { finish, graphic, variant: 0 },
    settings: { ...defaultEffects(''), ...effects },
  };
};
const group = (
  category: typeof effectPresetCategories[number]['id'],
  presets: BuiltInEffectPreset[],
) =>
  presets.map((item, index) => ({
    ...item,
    category,
    tags: [
      ...(item.tags ?? []),
      ...effectPresetCategories
        .find(value => value.id === category)!
        .tags.split(' '),
    ],
    design: { ...item.design, variant: index + 1 },
  }));

