import { Midi } from '@tonejs/midi';
import { MidiEvent, parseMidi, writeMidi } from 'midi-file';

import type { Melody } from 'app/services/MelodiesService/types';
import { chromaticNotes } from 'app/services/NotesService/chromaticNotes';
import { getNote } from 'app/services/NotesService/noteUtils';
import type { RecordingProject } from 'app/services/NotesService/slice/types';
import type { Octave } from 'app/services/NotesService/types';
import {
  isMicrotonalScale,
  noteTuningCents,
} from 'app/services/SettingsService/microtonal';

import type { Phrase } from './compose';
import { STEPS_PER_BEAT, timbrePrograms } from './options';

const timeSignature = '4/4';
const title = 'Generated melody';
const noteForMidi = (midi: number) =>
  getNote(chromaticNotes[midi % 12], (Math.floor(midi / 12) - 1) as Octave);

const phraseParts = (phrase: Phrase) => [
  { id: 'melody', name: 'Melody', notes: phrase.melody, velocity: 0.8 },
  {
    id: 'accompaniment',
    name: 'Accompaniment',
    notes: phrase.accompaniment,
    velocity: 0.58,
  },
];

export const phraseRecordingProject = (
  phrase: Phrase,
): Omit<RecordingProject, 'id'> => {
  const stepMs = 60000 / (phrase.bpm * STEPS_PER_BEAT);
  const settings: Omit<Melody, 'notes'> = {
    title,
    timbre: phrase.timbre,
    scale: phrase.scale,
    mode: phrase.mode,
    customScale: phrase.customScale,
    pitch: phrase.pitch,
    octave: 4,
    bpm: phrase.bpm,
    timeSignature,
  };
  return {
    title,
    activeTrackId: 'melody',
    tracks: phraseParts(phrase).map(({ id, name, notes }) => ({
      id,
      name,
      melody: {
        ...settings,
        notes: notes.map(({ midi, start, length }) => {
          const note = noteForMidi(midi);
          const cents = noteTuningCents(note, phrase);
          return {
            note,
            start: start * stepMs,
            duration: (start + length) * stepMs - start * stepMs,
            ...(cents
              ? {
                  expression: {
                    points: [
                      { position: 0, cents },
                      { position: 1, cents },
                    ],
                    techniques: [],
                  },
                }
              : {}),
          };
        }),
      },
    })),
  };
};

export const phrasePlayback = (phrase: Phrase): Melody => {
  const { tracks } = phraseRecordingProject(phrase);
  return {
    ...tracks[0].melody,
    notes: tracks.flatMap(track => track.melody.notes),
  };
};

const tuneMidi = (bytes: Uint8Array, phrase: Phrase) => {
  const midi = parseMidi(bytes);
  midi.tracks = midi.tracks.map(events => {
    const program = events.find(event => event.type === 'programChange');
    if (!program || program.type !== 'programChange') return events;
    // Independent tuning for simultaneous notes, with separate channels for each part.
    const available = Array.from(
      { length: 16 },
      (_, channel) => channel,
    ).filter(channel => channel !== 9 && channel % 2 === program.channel);
    const channels = new Map<number, number>();
    const tuned = events.map(event => {
      if (event.type !== 'noteOn' && event.type !== 'noteOff') return event;
      const cents = noteTuningCents(noteForMidi(event.noteNumber), phrase);
      if (!channels.has(cents)) channels.set(cents, available[channels.size]);
      return { ...event, channel: channels.get(cents)! };
    });
    return tuned.flatMap((event): MidiEvent[] => {
      if (event.type !== 'programChange') return [event];
      return Array.from(channels).flatMap(([cents, channel]): MidiEvent[] => [
        { ...event, channel },
        ...[
          [101, 0],
          [100, 0],
          [6, 2],
          [38, 0],
          [101, 127],
          [100, 127],
        ].map(
          ([controllerType, value]): MidiEvent => ({
            type: 'controller',
            deltaTime: 0,
            channel,
            controllerType,
            value,
          }),
        ),
        {
          type: 'pitchBend',
          deltaTime: 0,
          channel,
          value: Math.round((cents * 8192) / 200),
        },
      ]);
    });
  });
  return Uint8Array.from(writeMidi(midi));
};

export const encodePhraseMidi = (phrase: Phrase): Uint8Array => {
  const midi = new Midi();
  midi.header.name = title;
  midi.header.timeSignatures.push({ ticks: 0, timeSignature: [4, 4] });
  midi.header.setTempo(phrase.bpm);
  const stepTicks = midi.header.ppq / STEPS_PER_BEAT;
  phraseParts(phrase).forEach(({ name, notes, velocity }, channel) => {
    const track = midi.addTrack();
    track.name = name;
    track.channel = channel;
    track.instrument.number = timbrePrograms[phrase.timbre];
    notes.forEach(note =>
      track.addNote({
        midi: note.midi,
        ticks: note.start * stepTicks,
        durationTicks: note.length * stepTicks,
        velocity,
      }),
    );
  });
  const bytes = midi.toArray();
  return isMicrotonalScale(phrase.scale) ? tuneMidi(bytes, phrase) : bytes;
};
