import { expressionLabel } from 'app/services/MelodiesService/expression';
import type { NoteExpression } from 'app/services/MelodiesService/types';
import { tuningLabel } from 'app/services/SettingsService/microtonal';

/** Shared by the staff, tablature and PDF renderer. */
export const NoteExpressionMark = ({
  expression,
  x,
  y,
  width = 36,
}: {
  expression?: NoteExpression;
  x: number;
  y: number;
  width?: number;
}) => {
  if (!expression) return null;
  const { techniques, points } = expression;
  const wide = techniques.includes('wide-vibrato');
  const vibrato = wide || techniques.includes('vibrato');
  const bend = techniques.includes('bend');
  const slide = techniques.includes('slide');
  const last = points[points.length - 1]?.cents ?? 0;
  const peak = points.reduce(
    (best, point) =>
      Math.abs(point.cents) > Math.abs(best) ? point.cents : best,
    0,
  );
  const amount = Math.abs(peak) / 100;
  const first = points[0]?.cents ?? 0;
  const rising = last >= first;
  const release = Math.abs(last) < Math.abs(first) - 20;
  const returns =
    Math.abs(peak) > Math.max(Math.abs(first), Math.abs(last)) + 40;
  const down = release || peak < 0;
  const bendPath = returns
    ? `M ${x} ${y + 8} Q ${x + width / 2} ${y - 14} ${x + width} ${
        y + 8
      } m -5 -2 l 5 2 l -1 -5`
    : `M ${x} ${y + (down ? -3 : 8)} Q ${x + width * 0.6} ${
        y + (down ? -3 : 8)
      } ${x + width * 0.6} ${y + (down ? 8 : -3)} m -3 ${down ? -4 : 4} l 3 ${
        down ? 4 : -4
      } l 3 ${down ? -4 : 4}`;
  const bendText =
    amount >= 1.9 && amount <= 2.1
      ? 'full'
      : amount >= 0.9 && amount <= 1.1
      ? '½'
      : `${Math.round(amount * 100) / 200}`;
  return (
    <g
      role="img"
      aria-label={expressionLabel(expression)}
      data-note-expression={techniques.join(' ')}
    >
      <title>{expressionLabel(expression)}</title>
      {!techniques.length &&
        points.length > 0 &&
        points.every(p => p.cents === first) && (
          <text x={x + width / 2} y={y} fontSize="8" textAnchor="middle">
            {tuningLabel(first)}
          </text>
        )}
      {bend && (
        <>
          <path
            d={bendPath}
            fill="none"
            stroke="currentColor"
            strokeWidth="1.2"
          />
          <text x={x + width * 0.6} y={y - 6} fontSize="9" textAnchor="middle">
            {bendText}
          </text>
        </>
      )}
      {slide && (
        <>
          <line
            x1={x}
            x2={x + width}
            y1={y + (rising ? 9 : 0)}
            y2={y + (rising ? 0 : 9)}
            stroke="currentColor"
          />
          <text x={x + width / 2} y={y - 4} fontSize="8" textAnchor="middle">
            sl.
          </text>
        </>
      )}
      {vibrato && (
        <path
          d={Array.from(
            { length: 9 },
            (_, i) =>
              `${i ? 'L' : 'M'} ${x + (i * width) / 8} ${
                y +
                (bend || slide ? 21 : 4) +
                (i % 2 ? (wide ? 4 : 2) : wide ? -4 : -2)
              }`,
          ).join(' ')}
          fill="none"
          stroke="currentColor"
          strokeWidth={wide ? 1.8 : 1.2}
        />
      )}
    </g>
  );
};
