import { useEffect, useRef, useState } from 'react';

import {
  isInstrumentAudioRunning,
  loadVirtualGuitar,
  playVirtualGuitarNote,
  resumeAudio,
} from 'app/services/SynthesizerService';

import {
  bendAtDistance,
  gestureDeadZone,
  noteAtFret,
  slideFret,
} from './fretboard';

type GuitarVoice = NonNullable<ReturnType<typeof playVirtualGuitarNote>>;

interface PointerOrigin {
  x: number;
  y: number;
  type: string;
}

type Gesture =
  | { kind: 'bend'; cents: number; direction: number }
  | { kind: 'slide'; cents: number; fret: number };

export interface GuitarTabNote {
  id: number;
  string: number;
  fret: number;
  technique?:
    | { kind: 'bend'; cents: number; released: boolean }
    | { kind: 'slide'; targets: number[] };
}

export const guitarTabLength = 8;

interface HeldString extends GuitarTabNote {
  origin?: PointerOrigin;
  gesture?: Gesture;
  voice?: GuitarVoice;
  unlockOnRelease: boolean;
  released?: boolean;
  timer?: number;
}

export const useVirtualGuitar = (enabled: boolean) => {
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>(
    'loading',
  );
  const [attempt, setAttempt] = useState(0);
  const held = useRef(new Map<number, HeldString>());
  const [active, setActive] = useState<HeldString[]>([]);
  const nextTabId = useRef(0);
  const [tab, setTab] = useState<GuitarTabNote[]>([]);

  useEffect(() => {
    let current = true;
    loadVirtualGuitar().then(
      () => current && setStatus('ready'),
      () => current && setStatus('error'),
    );
    return () => {
      current = false;
    };
  }, [attempt]);

  useEffect(() => {
    if (!enabled) {
      setActive([]);
      return;
    }
    const strings = held.current;
    const clear = () => {
      strings.forEach(({ timer, voice }) => {
        window.clearTimeout(timer);
        voice?.stop();
      });
      strings.clear();
    };
    const reset = () => {
      clear();
      setActive([]);
    };
    const visibility = () => {
      if (document.hidden) reset();
    };
    window.addEventListener('blur', reset);
    window.addEventListener('pagehide', reset);
    document.addEventListener('visibilitychange', visibility);
    return () => {
      clear();
      window.removeEventListener('blur', reset);
      window.removeEventListener('pagehide', reset);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [enabled]);

  const refresh = () =>
    setActive(Array.from(held.current.values()).filter(note => note.voice));
  const cancel = (id: number) => {
    const note = held.current.get(id);
    if (!note) return;
    held.current.delete(id);
    window.clearTimeout(note.timer);
    note.voice?.stop();
    if (note.voice) refresh();
  };

  const start = (pointer: number, tabId: number) => {
    const fail = () => {
      if (held.current.get(pointer)?.id !== tabId) return;
      cancel(pointer);
      setStatus('error');
    };
    const pluck = () => {
      const note = held.current.get(pointer);
      if (note?.id !== tabId) return;
      const { string, fret, gesture, technique } = note;
      const voice = playVirtualGuitarNote(noteAtFret(string, fret));
      if (!voice) {
        fail();
        return;
      }
      if (gesture?.cents)
        voice.setPitchOffset(
          gesture.cents,
          gesture.kind === 'slide' ? 'step' : 'smooth',
        );
      note.voice = voice;
      if (!note.origin || note.released)
        note.timer = window.setTimeout(() => cancel(pointer), 360);
      setTab(current => [
        ...current.slice(1 - guitarTabLength),
        { id: tabId, string, fret, technique },
      ]);
      setStatus('ready');
      refresh();
    };
    if (status === 'ready' && isInstrumentAudioRunning()) pluck();
    else
      void Promise.all([resumeAudio(), loadVirtualGuitar()])
        .then(pluck)
        .catch(fail);
  };

  return {
    status,
    active,
    tab,
    retry: () => {
      setStatus('loading');
      setAttempt(count => count + 1);
    },
    play: (
      id: number,
      string: number,
      fret: number,
      origin?: PointerOrigin,
    ) => {
      if (!enabled) return;
      held.current.forEach((note, owner) => {
        if (note.string === string || owner === id) cancel(owner);
      });
      const tabId = nextTabId.current++;
      const unlockOnRelease =
        !!origin && origin.type !== 'mouse' && !isInstrumentAudioRunning();
      held.current.set(id, {
        id: tabId,
        string,
        fret,
        origin,
        unlockOnRelease,
      });
      if (!unlockOnRelease) start(id, tabId);
    },
    move: (id: number, x: number, y: number, cellOffset: number) => {
      const note = held.current.get(id);
      if (!note?.origin || note.released) return;
      const { origin } = note;
      const dx = x - origin.x;
      const dy = y - origin.y;
      if (
        !note.gesture &&
        Math.max(Math.abs(dx), Math.abs(dy)) <= gestureDeadZone
      )
        return;

      // Keep the first clear axis until release so drift on the other
      // axis does not switch techniques mid-gesture.
      const kind =
        note.gesture?.kind ?? (Math.abs(dx) > Math.abs(dy) ? 'slide' : 'bend');
      let gesture: Gesture;
      if (kind === 'slide') {
        const fret = slideFret(note.fret, cellOffset);
        if (note.gesture?.kind === 'slide' && fret === note.gesture.fret)
          return;
        gesture = { kind, fret, cents: (fret - note.fret) * 100 };
      } else {
        gesture = { kind, cents: bendAtDistance(dy), direction: Math.sign(dy) };
      }
      let technique = note.technique;
      if (gesture.cents !== (note.gesture?.cents ?? 0)) {
        note.voice?.setPitchOffset(
          gesture.cents,
          kind === 'slide' ? 'step' : 'smooth',
        );
        technique = tabTechnique(note, gesture);
        if (note.voice) {
          setTab(current =>
            current.map(entry =>
              entry.id === note.id ? { ...entry, technique } : entry,
            ),
          );
        }
      }
      held.current.set(id, { ...note, gesture, technique });
      if (note.voice) refresh();
    },
    release: (id: number) => {
      const note = held.current.get(id);
      if (!note || note.released) return;
      if (note.voice) {
        cancel(id);
        return;
      }
      // Keep a quick tap while the sample is loading. A fresh touch only
      // grants audio activation when the pointer is released.
      note.released = true;
      if (note.unlockOnRelease) start(id, note.id);
    },
    cancel,
    loseCapture: (id: number) => {
      if (!held.current.get(id)?.released) cancel(id);
    },
  };
};

const tabTechnique = (
  { fret, technique: previous }: GuitarTabNote,
  gesture: Gesture,
): GuitarTabNote['technique'] => {
  if (gesture.kind === 'bend') {
    const peak = previous?.kind === 'bend' ? previous.cents : 0;
    const cents = Math.max(peak, Math.round(gesture.cents));
    if (!cents) return previous;
    return { kind: 'bend', cents, released: gesture.cents === 0 };
  }
  const targets = previous?.kind === 'slide' ? previous.targets : [];
  const last = targets[targets.length - 1] ?? fret;
  const from = targets[targets.length - 2] ?? fret;
  // A continuous slide needs only its end fret. Keep any changes of direction.
  const continuing = Math.sign(last - from) === Math.sign(gesture.fret - last);
  return {
    kind: 'slide',
    targets: [...(continuing ? targets.slice(0, -1) : targets), gesture.fret],
  };
};
